import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import { getStr, KEY, saveSetting } from '../utils/settings';
/**
 * Campo que grava sozinho 600 ms depois da última tecla.
 */
export default class AdminText extends Component {
  timer = null;
  onremove() {
    if (this.timer) clearTimeout(this.timer);
  }
  view() {
    const {
      setting,
      label,
      help,
      type = 'text',
      placeholder,
      min,
      addon
    } = this.attrs;
    const id = 'MailReplyAdmin-' + setting;
    const secret = type === 'password';
    const input = m("input", {
      id: id,
      className: "FormControl",
      type: type,
      value: getStr(setting),
      placeholder: placeholder ?? '',
      min: min,
      step: type === 'number' ? 1 : undefined,
      autocomplete: secret ? 'new-password' : 'off',
      spellcheck: false,
      oninput: e => this.change(e.target.value)
    });
    return m("div", {
      className: 'Form-group' + (type === 'number' ? ' MailReplyAdmin-narrow' : '')
    }, m("label", {
      className: "MailReplyAdmin-label",
      for: id
    }, label), addon ? m("div", {
      className: "MailReplyAdmin-inputRow"
    }, input, addon) : input, help ? m("p", {
      className: "helpText"
    }, help) : null);
  }
  change(value) {
    const {
      setting
    } = this.attrs;
    app.data.settings[KEY + setting] = value;
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      this.timer = null;
      saveSetting(setting, value);
    }, 600);
  }
}
flarum.reg.add('ramon-mail-reply', 'admin/components/AdminText', AdminText);