import Component from 'flarum/common/Component';
import { t } from '../utils/trans';
import { parseReplyAddress } from '../utils/replyAddress';
const SAMPLE = [{
  part: 'user',
  text: 'u42'
}, {
  part: 'discussion',
  text: 'd1337'
}, {
  part: 'post',
  text: 'p9001'
}, {
  part: 'sig',
  text: '-3f9a1c0be47d52e8'
}];

/**
 * Prévia ao vivo do Reply-To gerado a partir da caixa digitada, com cada
 * pedaço do +tag destacado e explicado na legenda.
 */
export default class AliasPreview extends Component {
  view() {
    const parts = parseReplyAddress(this.attrs.replyAddress.trim());
    return m("div", {
      className: 'MailReplyAdmin-alias' + (parts ? '' : ' is-pending'),
      "aria-live": "polite"
    }, m("div", {
      className: "MailReplyAdmin-alias-label"
    }, t('alias_preview_label')), m("code", {
      className: "MailReplyAdmin-alias-address"
    }, m("span", {
      className: "MailReplyAdmin-alias-local"
    }, parts?.local ?? 'inbox'), m("span", {
      className: "MailReplyAdmin-alias-plus"
    }, "+"), SAMPLE.map(({
      part,
      text
    }) => m("span", {
      className: "MailReplyAdmin-alias-tag",
      "data-part": part
    }, text)), m("span", {
      className: "MailReplyAdmin-alias-domain"
    }, "@", parts?.domain ?? 'reply.example.com')), m("ul", {
      className: "MailReplyAdmin-alias-legend"
    }, SAMPLE.map(({
      part
    }) => m("li", {
      "data-part": part
    }, t('alias_legend_' + part)))), m("div", {
      className: "MailReplyAdmin-alias-note"
    }, parts ? t('alias_base', {
      address: m("code", null, `${parts.local}@${parts.domain}`)
    }) : t('alias_pending')));
  }
}
flarum.reg.add('ramon-mail-reply', 'admin/components/AliasPreview', AliasPreview);