import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import AdminCard from './AdminCard';
import StatusState from '../utils/StatusState';
import { onSettingSaved } from '../utils/settings';
import { t, ts } from '../utils/trans';
import { CARDS, cardVisible, GROUPS, groupVisible } from '../cards';
const TAB_STORAGE_KEY = 'ramon-mail-reply.admin.tab';

/**
 * Aba ativa, lembrada entre visitas: cada gravação redesenha a página e
 * voltar sempre para a primeira aba seria perder o lugar.
 */
let activeGroup = (() => {
  try {
    const saved = localStorage.getItem(TAB_STORAGE_KEY);
    if (saved && GROUPS.some(g => g.key === saved)) return saved;
  } catch {
    return 'general';
  }
  return 'general';
})();
let query = '';
function setGroup(key) {
  activeGroup = key;
  query = '';
  try {
    localStorage.setItem(TAB_STORAGE_KEY, key);
  } catch {
    return;
  }
}
const cardTitle = card => ts('card_' + card.id + '_title');
const matchesQuery = (card, q) => `${cardTitle(card)} ${card.keywords}`.toLowerCase().includes(q);

/**
 * Casca da página: abas por grupo, busca que varre os cards visíveis de
 * todos os grupos e os cards do grupo ativo. Cada controle salva sozinho.
 */
export default class SettingsPanel extends Component {
  status = new StatusState();
  oninit(vnode) {
    super.oninit(vnode);
    onSettingSaved(() => this.status.reloadSoon());
    this.status.load();
  }
  view() {
    if (!groupVisible(activeGroup)) setGroup('general');
    const q = query.trim().toLowerCase();
    const candidates = CARDS.filter(cardVisible);
    const shown = q ? candidates.filter(card => matchesQuery(card, q)) : candidates.filter(card => card.group === activeGroup);
    return m("div", {
      className: "MailReplyAdmin-settings"
    }, m("div", {
      className: "MailReplyAdmin-toolbar"
    }, m("nav", {
      className: "MailReplyAdmin-tabs",
      role: "tablist",
      "aria-label": ts('groups_aria')
    }, GROUPS.filter(g => groupVisible(g.key)).map(g => {
      const isActive = !q && g.key === activeGroup;
      return m("button", {
        key: g.key,
        type: "button",
        role: "tab",
        "aria-selected": isActive ? 'true' : 'false',
        className: 'MailReplyAdmin-tab' + (isActive ? ' is-active' : ''),
        onclick: () => setGroup(g.key)
      }, m(Icon, {
        name: g.icon
      }), m("span", null, t('group_' + g.key)), m("span", {
        className: "MailReplyAdmin-tabCount"
      }, candidates.filter(card => card.group === g.key).length));
    })), m("div", {
      className: "MailReplyAdmin-search"
    }, m(Icon, {
      name: "fas fa-search"
    }), m("input", {
      type: "search",
      className: "MailReplyAdmin-searchInput",
      value: query,
      placeholder: ts('search_placeholder'),
      "aria-label": ts('search_placeholder'),
      oninput: e => query = e.target.value
    }), query ? m("button", {
      type: "button",
      className: "MailReplyAdmin-searchClear",
      "aria-label": ts('search_clear'),
      onclick: () => query = ''
    }, m(Icon, {
      name: "fas fa-times"
    })) : null)), shown.length === 0 ? m("p", {
      className: "MailReplyAdmin-empty"
    }, t('search_empty')) : shown.map(card => m(AdminCard, {
      key: card.id,
      title: cardTitle(card),
      icon: card.icon
    }, card.body(this.status))));
  }
}
flarum.reg.add('ramon-mail-reply', 'admin/components/SettingsPanel', SettingsPanel);